//! Tests that must hold identically for the C backend and the pure Rust one.
//!
//! Run under both and check they agree:
//!
//! ```sh
//! cargo test --manifest-path secp256k1_sys_pure/Cargo.toml --test backend_parity
//! RUSTFLAGS="--cfg secp256k1_pure" cargo test --manifest-path secp256k1_sys_pure/Cargo.toml --test backend_parity
//! ```
//!
//! The assertions are deliberately either published constants or algebraic
//! identities, rather than values dumped out of one implementation. A vector
//! generated by the C library only proves the pure backend copies it, whereas an
//! identity like `1*G + 1*G == 2*G` is an independent statement about the group
//! that both backends have to satisfy.
//!
//! Only operations that both backends implement are covered. Signing and
//! verification are absent from the pure backend on purpose, so they are not
//! tested here; see `src/pure.rs`.

use secp256k1::{All, Parity, PublicKey, Scalar, Secp256k1, SecretKey, XOnlyPublicKey};

fn secp() -> Secp256k1<All> {
    Secp256k1::new()
}

/// The generator, compressed. From SEC 2 v2, section 2.4.1.
const G_COMPRESSED: [u8; 33] = [
    0x02, 0x79, 0xBE, 0x66, 0x7E, 0xF9, 0xDC, 0xBB, 0xAC, 0x55, 0xA0, 0x62, 0x95, 0xCE, 0x87, 0x0B,
    0x07, 0x02, 0x9B, 0xFC, 0xDB, 0x2D, 0xCE, 0x28, 0xD9, 0x59, 0xF2, 0x81, 0x5B, 0x16, 0xF8, 0x17,
    0x98,
];

/// The generator, uncompressed. Same source.
const G_UNCOMPRESSED: [u8; 65] = [
    0x04, 0x79, 0xBE, 0x66, 0x7E, 0xF9, 0xDC, 0xBB, 0xAC, 0x55, 0xA0, 0x62, 0x95, 0xCE, 0x87, 0x0B,
    0x07, 0x02, 0x9B, 0xFC, 0xDB, 0x2D, 0xCE, 0x28, 0xD9, 0x59, 0xF2, 0x81, 0x5B, 0x16, 0xF8, 0x17,
    0x98, 0x48, 0x3A, 0xDA, 0x77, 0x26, 0xA3, 0xC4, 0x65, 0x5D, 0xA4, 0xFB, 0xFC, 0x0E, 0x11, 0x08,
    0xA8, 0xFD, 0x17, 0xB4, 0x48, 0xA6, 0x85, 0x54, 0x19, 0x9C, 0x47, 0xD0, 0x8F, 0xFB, 0x10, 0xD4,
    0xB8,
];

/// The group order `n`. Scalars must be strictly below this.
const CURVE_ORDER: [u8; 32] = [
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFE,
    0xBA, 0xAE, 0xDC, 0xE6, 0xAF, 0x48, 0xA0, 0x3B, 0xBF, 0xD2, 0x5E, 0x8C, 0xD0, 0x36, 0x41, 0x41,
];

/// The field modulus `p`. x-coordinates must be strictly below this.
const FIELD_MODULUS: [u8; 32] = [
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
    0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFE, 0xFF, 0xFF, 0xFC, 0x2F,
];

/// A 32-byte big-endian encoding of a small integer.
fn scalar_bytes(n: u8) -> [u8; 32] {
    let mut buf = [0u8; 32];
    buf[31] = n;
    buf
}

fn seckey(n: u8) -> SecretKey {
    SecretKey::from_slice(&scalar_bytes(n)).unwrap()
}

/// `n * G` for a small `n`.
fn pubkey(n: u8) -> PublicKey {
    PublicKey::from_secret_key(&secp(), &seckey(n))
}

fn tweak(n: u8) -> Scalar {
    Scalar::from_be_bytes(scalar_bytes(n)).unwrap()
}

#[test]
fn generator_is_the_published_constant() {
    assert_eq!(pubkey(1).serialize(), G_COMPRESSED);
    assert_eq!(pubkey(1).serialize_uncompressed(), G_UNCOMPRESSED);
}

#[test]
fn compressed_and_uncompressed_parse_to_the_same_key() {
    let from_compressed = PublicKey::from_slice(&G_COMPRESSED).unwrap();
    let from_uncompressed = PublicKey::from_slice(&G_UNCOMPRESSED).unwrap();
    assert_eq!(from_compressed, from_uncompressed);
    assert_eq!(from_compressed.serialize(), G_COMPRESSED);
    assert_eq!(from_uncompressed.serialize_uncompressed(), G_UNCOMPRESSED);
}

#[test]
fn pubkey_parse_rejects_invalid_encodings() {
    // Wrong length.
    assert!(PublicKey::from_slice(&[]).is_err());
    assert!(PublicKey::from_slice(&G_COMPRESSED[..32]).is_err());
    assert!(PublicKey::from_slice(&G_UNCOMPRESSED[..64]).is_err());

    // Bad prefix byte: valid x, but 0x04 is only for the 65-byte form.
    let mut bad_prefix = G_COMPRESSED;
    bad_prefix[0] = 0x04;
    assert!(PublicKey::from_slice(&bad_prefix).is_err());
    bad_prefix[0] = 0x00;
    assert!(PublicKey::from_slice(&bad_prefix).is_err());

    // x = 0 is not on the curve: y^2 = 7 has no square root mod p.
    let mut not_on_curve = [0u8; 33];
    not_on_curve[0] = 0x02;
    assert!(PublicKey::from_slice(&not_on_curve).is_err());

    // x = p is out of range for the field.
    let mut x_is_modulus = [0u8; 33];
    x_is_modulus[0] = 0x02;
    x_is_modulus[1..].copy_from_slice(&FIELD_MODULUS);
    assert!(PublicKey::from_slice(&x_is_modulus).is_err());
}

#[test]
fn seckey_range_is_one_to_order_exclusive() {
    // Zero is not a valid secret key, one is.
    assert!(SecretKey::from_slice(&[0u8; 32]).is_err());
    assert!(SecretKey::from_slice(&scalar_bytes(1)).is_ok());

    // n is out of range; n-1 is the largest valid key.
    assert!(SecretKey::from_slice(&CURVE_ORDER).is_err());
    let mut order_minus_one = CURVE_ORDER;
    order_minus_one[31] -= 1;
    assert!(SecretKey::from_slice(&order_minus_one).is_ok());

    // Everything above n is out of range too.
    assert!(SecretKey::from_slice(&[0xFF; 32]).is_err());
}

#[test]
fn scalar_range_matches_seckey_range_except_zero() {
    // Unlike a secret key, a tweak scalar is allowed to be zero.
    assert!(Scalar::from_be_bytes([0u8; 32]).is_ok());
    assert!(Scalar::from_be_bytes(CURVE_ORDER).is_err());
    assert!(Scalar::from_be_bytes([0xFF; 32]).is_err());
}

#[test]
fn adding_one_to_the_generator_gives_two_g() {
    let two_g = pubkey(1).add_exp_tweak(&secp(), &tweak(1)).unwrap();
    assert_eq!(two_g, pubkey(2));
}

#[test]
fn scalar_addition_agrees_with_point_addition() {
    // (2 + 3)*G == 5*G, computed both in the scalar field and on the curve.
    let five_by_scalar = seckey(2).add_tweak(&tweak(3)).unwrap();
    assert_eq!(five_by_scalar, seckey(5));
    assert_eq!(
        PublicKey::from_secret_key(&secp(), &five_by_scalar),
        pubkey(5)
    );

    let five_by_point = pubkey(2).add_exp_tweak(&secp(), &tweak(3)).unwrap();
    assert_eq!(five_by_point, pubkey(5));
}

#[test]
fn scalar_multiplication_agrees_with_point_multiplication() {
    // (3 * 4)*G == 12*G
    let twelve_by_scalar = seckey(3).mul_tweak(&tweak(4)).unwrap();
    assert_eq!(twelve_by_scalar, seckey(12));

    let twelve_by_point = pubkey(3).mul_tweak(&secp(), &tweak(4)).unwrap();
    assert_eq!(twelve_by_point, pubkey(12));
}

#[test]
fn combine_sums_points() {
    assert_eq!(pubkey(2).combine(&pubkey(3)).unwrap(), pubkey(5));

    let summed = PublicKey::combine_keys(&[&pubkey(1), &pubkey(2), &pubkey(4)]).unwrap();
    assert_eq!(summed, pubkey(7));

    // Combining nothing has no answer.
    assert!(PublicKey::combine_keys(&[]).is_err());
}

#[test]
fn point_negation_is_an_involution() {
    for n in 1..=5u8 {
        assert_eq!(pubkey(n).negate(&secp()).negate(&secp()), pubkey(n));
    }
}

#[test]
fn seckey_negation_is_an_involution() {
    for n in 1..=5u8 {
        assert_eq!(seckey(n).negate().negate(), seckey(n));
    }
}

#[test]
fn negating_a_key_negates_its_point() {
    // (-k)*G must be the point with the same x and the opposite y.
    for n in 1..=5u8 {
        let negated_point = PublicKey::from_secret_key(&secp(), &seckey(n).negate());
        let (x_of_negated, parity_of_negated) = negated_point.x_only_public_key();
        let (x, parity) = pubkey(n).x_only_public_key();
        assert_eq!(x_of_negated, x);
        assert_ne!(parity_of_negated, parity);
    }
}

#[test]
fn lift_x_recovers_the_even_y_point() {
    for n in 1..=5u8 {
        let (xonly, parity) = pubkey(n).x_only_public_key();
        let lifted = XOnlyPublicKey::from_slice(&xonly.serialize()).unwrap();
        assert_eq!(lifted, xonly);

        // Lifting always picks even y, so it recovers the original key only when
        // that key already had even y. The stated parity recovers it either way.
        assert_eq!(lifted.public_key(parity), pubkey(n));
        if parity == Parity::Even {
            assert_eq!(lifted.public_key(Parity::Even), pubkey(n));
        } else {
            assert_ne!(lifted.public_key(Parity::Even), pubkey(n));
        }
    }
}

#[test]
fn xonly_parse_rejects_x_not_on_curve() {
    // x = 0 has no corresponding y.
    assert!(XOnlyPublicKey::from_slice(&[0u8; 32]).is_err());
    // x = p is out of field range.
    assert!(XOnlyPublicKey::from_slice(&FIELD_MODULUS).is_err());
    // Wrong length.
    assert!(XOnlyPublicKey::from_slice(&[0u8; 31]).is_err());
    assert!(XOnlyPublicKey::from_slice(&[0u8; 33]).is_err());
}

#[test]
fn xonly_tweak_add_check_accepts_exactly_the_computed_tweak() {
    for n in 1..=4u8 {
        let (internal, _) = pubkey(n).x_only_public_key();
        let t = tweak(n + 1);
        let (tweaked, parity) = internal.add_tweak(&secp(), &t).unwrap();

        let wrong_parity = if parity == Parity::Even {
            Parity::Odd
        } else {
            Parity::Even
        };

        assert!(internal.tweak_add_check(&secp(), &tweaked, parity, t));
        // The wrong parity must not verify.
        assert!(!internal.tweak_add_check(&secp(), &tweaked, wrong_parity, t));
        // Nor a different tweak.
        assert!(!internal.tweak_add_check(&secp(), &tweaked, parity, tweak(n + 2)));
    }
}

#[test]
fn xonly_tweak_agrees_with_full_point_tweak() {
    // Tweaking an x-only key is defined as tweaking its even-y lift, so it must
    // agree with doing that explicitly through the full-point API.
    for n in 1..=4u8 {
        let (internal, _) = pubkey(n).x_only_public_key();
        let t = tweak(n + 1);

        let (tweaked_xonly, parity) = internal.add_tweak(&secp(), &t).unwrap();
        let via_full_point = internal
            .public_key(Parity::Even)
            .add_exp_tweak(&secp(), &t)
            .unwrap();
        let (expected_xonly, expected_parity) = via_full_point.x_only_public_key();

        assert_eq!(tweaked_xonly, expected_xonly);
        assert_eq!(parity, expected_parity);
    }
}

#[test]
fn keypair_roundtrips_through_its_halves() {
    for n in 1..=5u8 {
        let sk = seckey(n);
        let keypair = sk.keypair(&secp());
        assert_eq!(SecretKey::from_keypair(&keypair), sk);
        assert_eq!(keypair.public_key(), pubkey(n));

        let (xonly, parity) = keypair.x_only_public_key();
        let (expected_xonly, expected_parity) = pubkey(n).x_only_public_key();
        assert_eq!(xonly, expected_xonly);
        assert_eq!(parity, expected_parity);
    }
}

#[test]
fn pubkey_ordering_follows_compressed_serialization() {
    let mut keys = [pubkey(1), pubkey(2), pubkey(3), pubkey(4), pubkey(5)];
    keys.sort();
    for pair in keys.windows(2) {
        assert!(pair[0].serialize() <= pair[1].serialize());
    }
}

#[test]
fn xonly_ordering_follows_serialization() {
    let mut keys = [
        pubkey(1).x_only_public_key().0,
        pubkey(2).x_only_public_key().0,
        pubkey(3).x_only_public_key().0,
        pubkey(4).x_only_public_key().0,
        pubkey(5).x_only_public_key().0,
    ];
    keys.sort();
    for pair in keys.windows(2) {
        assert!(pair[0].serialize() <= pair[1].serialize());
    }
}
